	go func() {
		log.Print("starting goroutine")

		defer func() {
			s.newWorker(input, accrualSystemAddress, updateOrder)
			if x := recover(); x != nil {
				log.Print("run time panic: ", x)
			}
		}()

		for {
			for o := range input {
				resp, err := http.Get(accrualSystemAddress + "/api/orders/" + o.number)
