								err := updateOrder(order)
								if err != nil {
									o.status = order.Status
									input <- o
									log.Printf("go number: %s, err: %s", o.number, err.Error())
									return
								}
							}
						}(o, order)
					default:
						log.Printf("go number: %s, status: %s", o.number, order.Status)
						go func(o orderStr) {
							input <- o
						}(o)
					}
				case http.StatusTooManyRequests:
					log.Printf("go number: %s, status: %s", o.number, resp.Status)
					go func(o orderStr) {
						input <- o
					}(o)
					atoi, err := strconv.Atoi(resp.Header.Get("Retry-After"))
					if err != nil {
						log.Printf("go number: %s, err: %s", o.number, err.Error())
						time.Sleep(time.Second * 15)
					} else {
						time.Sleep(time.Second * time.Duration(atoi))
					}
				case http.StatusInternalServerError:
					log.Printf("go number: %s, status: %s", o.number, resp.Status)
					go func(o orderStr) {
						input <- o
					}(o)
				case http.StatusNoContent:
					log.Printf("go number: %s, status: %s", o.number, resp.Status)
					go func(o orderStr) {
						if o.status != "PROCESSING" {
							err := updateOrder(Order{Status: "PROCESSING", Number: o.number})
							if err != nil {
								log.Printf("go number: %s, err: %s", o.number, err.Error())
								return
							}
							o.status = "PROCESSING"
						}
						input <- o
					}(o)
				default:
					log.Printf("go number: %s, status: %s", o.number, resp.Status)
					go func(o orderStr) {
						input <- o
					}(o)
				}
			}
		}
	}()
}

