175: 					if err != nil {
176: 						go func(o orderStr) {
177: 							input <- o
178: 						}(o)
179: 						log.Printf("go number: %s, err: %s", o.number, err.Error())
180: 						return
181: 					}
182: 
183: 					order.Number = o.number
184: 
185: 					switch order.Status {
186: 					case "PROCESSING":
187: 						log.Printf("go number: %s, status: %s", o.number, order.Status)
188: 						go func(o orderStr, order Order) {
189: 							if o.status != order.Status {
190: 								err := updateOrder(order)
191: 								if err != nil {
192: 									log.Printf("go number: %s, err: %s", o.number, err.Error())
193: 									return
194: 								}
195: 								o.status = "PROCESSING"
196: 							}
197: 							input <- o
198: 						}(o, order)
199: 					case "INVALID", "PROCESSED":
200: 						log.Printf("go number: %s, status: %s, accrual: %g", o.number, order.Status, order.Accrual)
201: 						go func(o orderStr, order Order) {
202: 							if o.status != order.Status {
203: 								err := updateOrder(order)
204: 								if err != nil {
205: 									o.status = order.Status
206: 									input <- o
207: 									log.Printf("go number: %s, err: %s", o.number, err.Error())
208: 									return
209: 								}
210: 							}
211: 						}(o, order)
212: 					default:
213: 						log.Printf("go number: %s, status: %s", o.number, order.Status)
214: 						go func(o orderStr) {
215: 							input <- o
216: 						}(o)
217: 					}
218: 				case http.StatusTooManyRequests:
219: 					log.Printf("go number: %s, status: %s", o.number, resp.Status)
220: 					go func(o orderStr) {
221: 						input <- o
222: 					}(o)
223: 					atoi, err := strconv.Atoi(resp.Header.Get("Retry-After"))
224: 					if err != nil {
225: 						log.Printf("go number: %s, err: %s", o.number, err.Error())
226: 						time.Sleep(time.Second * 15)
227: 					} else {
228: 						time.Sleep(time.Second * time.Duration(atoi))
229: 					}
230: 				case http.StatusInternalServerError:
231: 					log.Printf("go number: %s, status: %s", o.number, resp.Status)
232: 					go func(o orderStr) {
233: 						input <- o
234: 					}(o)
235: 				case http.StatusNoContent:
236: 					log.Printf("go number: %s, status: %s", o.number, resp.Status)
237: 					go func(o orderStr) {
238: 						if o.status != "PROCESSING" {
239: 							err := updateOrder(Order{Status: "PROCESSING", Number: o.number})
240: 							if err != nil {
241: 								log.Printf("go number: %s, err: %s", o.number, err.Error())
242: 								return
243: 							}
244: 							o.status = "PROCESSING"
245: 						}
246: 						input <- o
247: 					}(o)
248: 				default:
249: 					log.Printf("go number: %s, status: %s", o.number, resp.Status)
250: 					go func(o orderStr) {
251: 						input <- o
252: 					}(o)
253: 				}
254: 			}
255: 		}
256: 	}()
257: }
