259: func (db *DataBase) updateOrder(order Order) error {
260: 	exec, err := db.DB.Exec(dbUpdateOrder, order.Status, order.Accrual, order.Number)
261: 	if err != nil {
262: 		return err
263: 	}
264: 
265: 	affected, err := exec.RowsAffected()
266: 	if err != nil {
267: 		return err
268: 	}
269: 
270: 	if affected == 0 {
271: 		return errors.New("failed update order")
272: 	}
273: 
274: 	log.Printf("update order: number: %s, status: %s, accrual: %g", order.Number, order.Status, order.Accrual)
275: 
276: 	return nil
277: }
