279: func (db *DataBase) GetOrders(cookie string) ([]Order, error) {
280: 	var login string
281: 	if err := db.DB.QueryRow(dbGetLogin, cookie).Scan(&login); err != nil {
282: 		if !errors.Is(err, sql.ErrNoRows) {
283: 			return nil, err
284: 		}
285: 
286: 		return nil, db.Err.NoAuthorization
287: 	}
288: 
289: 	rows, err := db.DB.Query(dbGetOrders, login)
290: 	if err != nil {
291: 		return nil, err
292: 	}
293: 
294: 	var orders []Order
295: 	for rows.Next() {
296: 		var order Order
297: 		var accrual sql.NullFloat64
298: 		if err = rows.Scan(&order.Number, &order.Status, &accrual, &order.UploadedAt); err != nil {
299: 			return nil, err
300: 		}
301: 
302: 		order.Accrual = accrual.Float64
303: 
304: 		orders = append(orders, order)
305: 	}
306: 
307: 	if err = rows.Err(); err != nil {
308: 		return nil, err
309: 	}
310: 
311: 	if orders == nil {
312: 		return nil, db.Err.Empty
313: 	}
314: 
315: 	return orders, nil
316: }
